import type { IApi } from '../../types.ts'

/**
 * `ssr: {}` renders pages on the server (dev server, `cormi preview` and the
 * production server), with `serverLoader` data embedded for hydration.
 * The server entry itself is generated by `tmpFiles` (`.cormi/server.ts`).
 */
export default (api: IApi) => {
  api.describe({
    key: 'ssr',
    config: {
      schema: ({ zod }) => zod.object({
        /** wrap route components in `<Suspense>` (default true) */
        useStream: zod.boolean(),
      }).partial(),
      onChange: api.ConfigChangeType.regenerateTmpFiles,
    },
    enableBy: api.EnableBy.config,
  })

  api.onCheck(() => {
    if (api.config.history?.type && api.config.history.type !== 'browser') {
      throw new Error('`ssr` only works with `history: { type: \'browser\' }`.')
    }
  })
}
